    {"name": "active", "type": "boolean", "required": True},
]}

def run(text, sch=mapped, bom=False):
    if isinstance(text, str): text = text.encode()
    if bom: text = b"\xef\xbb\xbf" + text
    with tempfile.NamedTemporaryFile(suffix=".jsonl", delete=False) as f:
        f.write(text); p = f.name
    r = normalize_jsonl(p, sch)
    os.unlink(p)
    return r

# 1. basic happy path with mapping, trimming
r = run('{"display_name":" Maya ","purchase_count":"3","active":"TRUE"}\n')
print("1", r)

# 2. blank lines preserve physical numbering; empty file zero
r = run('\n  \n{"display_name":"a","purchase_count":2,"active":false}\n\n')
print("2", r["records"], r["accepted"], r["errors"])
r = run("")
print("2b empty", r)
r = run("   \n\t\n  \n")
print("2c blank-only", r)

# 3. BOM + first valid line
r = run('{"display_name":"a","purchase_count":2,"active":false}\n', bom=True)
print("3 bom", r["records"], r["errors"])

# 4. invalid JSON / non-object top level / duplicate keys
r = run('{bad\n42\n[1,2]\n"str"\nnull\n{"a":1,"a":2}\n')
print("4 rows", [e["row"] for e in r["errors"]])
for e in r["errors"]: print("  ", e)

# 5. missing/extra keys
r = run('{"display_name":"a","active":true}\n{"display_name":"a","purchase_count":1,"active":true,"x":9}\n')
for e in r["errors"]: print("5", e)

# 6. types: floats, exp, bool-as-int, arrays, objects, NaN/Infinity
r = run('''{"display_name":"a","purchase_count":1.5,"active":true}
{"display_name":"a","purchase_count":1e3,"active":true}
{"display_name":"a","purchase_count":true,"active":true}
{"display_name":["a"],"purchase_count":1,"active":true}
{"display_name":{"k":"v"},"purchase_count":1,"active":true}
{"display_name":"a","purchase_count":1,"active":NaN}
{"display_name":"a","purchase_count":Infinity,"active":true}
{"display_name":"a","purchase_count":-Infinity,"active":true}
{"display_name":"a","purchase_count":"nope","active":true}
{"display_name":"a","purchase_count":" 7 ","active":"FaLsE"}
{"display_name":"","purchase_count":null,"active":true}
''')
for e in r["errors"]: print("6", e["row"], e["errors"])
print("6 accepted:", r["records"])

# 7. ordering: records retain input order, field errors in schema order
r = run('''{"display_name":"z","purchase_count":1,"active":true}
{"display_name":9,"purchase_count":"x","active":"yes"}
{"display_name":"y","purchase_count":2,"active":false}
''')
print("7 recs", r["records"])
print("7 errs", r["errors"])

# 8. required null/empty rejection (active required)
r = run('''{"display_name":"a","purchase_count":null,"active":null}
{"display_name":"  ","purchase_count":1,"active":true}
{"display_name":"a","purchase_count":"","active":true}
''')
for e in r["errors"]: print("8", e["row"], e["errors"])
print("8 accepted", r["records"])

# 9. schema errors still raise
for bad in ({"columns":[{"name":"x","type":"date"}]},
            {"columns":[{"name":"x","type":"string","source":""}]}):
    try:
        run('{"x":"y"}\n', bad); print("9 NO RAISE", bad)
    except ValueError as ex: print("9 raised:", ex)

# 10. missing file raises OSError
try:
    normalize_jsonl("/nonexistent/nope.jsonl", schema); print("10 NO RAISE")
except OSError as e: print("10 OSError ok")

# 11. decode error
import tempfile as t
p = t.mktemp()
open(p,"wb").write(b'\xff\xfe bad')
try:
    normalize_jsonl(p, schema); print("11 NO RAISE")
except UnicodeDecodeError: print("11 UnicodeDecodeError ok")
finally: os.unlink(p)
